import{_ as d,I as r,c as s,o as t,a5 as o,b as i,w as c,a as n,J as l,a6 as E}from"./chunks/framework.BmNIwhaK.js";const C=JSON.parse('{"title":"SyncWatchアーキテクチャ — 8大グローバル脅威フィード収集、5段階SSRFガードおよびデュアルルールコンパイラ","description":"SyncWatchの8大グローバル脅威フィード（OSV.dev、GitHub GHSA、NVD CVE、CISA KEV、Nuclei、OWASP CRS、MITRE ATT&CK、KISA）収集チャネル、5段階SSRF防御ガード、WatchRuleCompilerServiceデュアルセキュリティルールコンパイルおよび独自サンドボックス検証アーキテクチャを説明します。","frontmatter":{"title":"SyncWatchアーキテクチャ — 8大グローバル脅威フィード収集、5段階SSRFガードおよびデュアルルールコンパイラ","description":"SyncWatchの8大グローバル脅威フィード（OSV.dev、GitHub GHSA、NVD CVE、CISA KEV、Nuclei、OWASP CRS、MITRE ATT&CK、KISA）収集チャネル、5段階SSRF防御ガード、WatchRuleCompilerServiceデュアルセキュリティルールコンパイルおよび独自サンドボックス検証アーキテクチャを説明します。","sidebarTitle":"アーキテクチャ & ルールコンパイラ","sort":2,"head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/syncwatch/architecture"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/syncwatch/architecture"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/syncwatch/architecture"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/syncwatch/architecture"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/syncwatch/architecture"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"SyncWatchアーキテクチャ — 8大グローバル脅威フィード収集、5段階SSRFガードおよびデュアルルールコンパイラ | Empasy Docs"}],["meta",{"property":"og:description","content":"SyncWatchの8大グローバル脅威フィード（OSV.dev、GitHub GHSA、NVD CVE、CISA KEV、Nuclei、OWASP CRS、MITRE ATT&CK、KISA）収集チャネル、5段階SSRF防御ガード、WatchRuleCompilerServiceデュアルセキュリティルールコンパイルおよび独自サンドボックス検証アーキテクチャを説明します。"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/syncwatch/architecture"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"SyncWatchアーキテクチャ — 8大グローバル脅威フィード収集、5段階SSRFガードおよびデュアルルールコンパイラ | Empasy Docs"}],["meta",{"name":"twitter:description","content":"SyncWatchの8大グローバル脅威フィード（OSV.dev、GitHub GHSA、NVD CVE、CISA KEV、Nuclei、OWASP CRS、MITRE ATT&CK、KISA）収集チャネル、5段階SSRF防御ガード、WatchRuleCompilerServiceデュアルセキュリティルールコンパイルおよび独自サンドボックス検証アーキテクチャを説明します。"}],["script",{"type":"application/ld+json","data-empasy-page-jsonld":"true"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"SyncWatchアーキテクチャ — 8大グローバル脅威フィード収集、5段階SSRFガードおよびデュアルルールコンパイラ\\",\\"description\\":\\"SyncWatchの8大グローバル脅威フィード（OSV.dev、GitHub GHSA、NVD CVE、CISA KEV、Nuclei、OWASP CRS、MITRE ATT&CK、KISA）収集チャネル、5段階SSRF防御ガード、WatchRuleCompilerServiceデュアルセキュリティルールコンパイルおよび独自サンドボックス検証アーキテクチャを説明します。\\",\\"url\\":\\"https://doc.empasy.com/ja/syncwatch/architecture\\",\\"inLanguage\\":\\"ja-JP\\",\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://doc.empasy.com/ja/syncwatch/architecture\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Empasy Inc.\\",\\"url\\":\\"https://empasy.io/\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Empasy Inc.\\",\\"url\\":\\"https://empasy.io/\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://doc.empasy.com/images/favicon.png\\"}}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Empasy Docs (JA)\\",\\"item\\":\\"https://doc.empasy.com/ja/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"SyncWatchアーキテクチャ — 8大グローバル脅威フィード収集、5段階SSRFガードおよびデュアルルールコンパイラ\\",\\"item\\":\\"https://doc.empasy.com/ja/syncwatch/architecture\\"}]}]}"]]},"headers":[],"relativePath":"ja/syncwatch/architecture.md","filePath":"ja/syncwatch/architecture.md","lastUpdated":1795293539000}'),S={name:"ja/syncwatch/architecture.md"};function A(h,e,p,g,_,m){const a=r("Mermaid");return t(),s("div",null,[e[1]||(e[1]=o('<h1 id="syncwatchシステムアーキテクチャおよびデュアルルールコンパイラ" tabindex="-1">SyncWatchシステムアーキテクチャおよびデュアルルールコンパイラ <a class="header-anchor" href="#syncwatchシステムアーキテクチャおよびデュアルルールコンパイラ" aria-label="Permalink to “SyncWatchシステムアーキテクチャおよびデュアルルールコンパイラ”">​</a></h1><p><code>SyncWatch</code>は、外部の脅威インテリジェンスを安全に取り込み、誤検知（False Positive）のない高信頼な点検・防御ルールへ変換するために、<strong>8大グローバル脅威フィード多チャネル正規化コレクター</strong>、<strong>5段階SSRFガード</strong>、<strong><code>WatchRuleCompilerService</code>デュアルコンパイラ</strong>、および<strong>独自サンドボックス検証器</strong>で構成されています。</p><hr><h2 id="_1-6大脅威収集チャネルおよび8大グローバル脅威フィードの正規化" tabindex="-1">1. 6大脅威収集チャネルおよび8大グローバル脅威フィードの正規化 <a class="header-anchor" href="#_1-6大脅威収集チャネルおよび8大グローバル脅威フィードの正規化" aria-label="Permalink to “1. 6大脅威収集チャネルおよび8大グローバル脅威フィードの正規化”">​</a></h2><p><code>SyncWatch</code>は、<strong>8大グローバル脅威フィード（OSV.dev、GitHub GHSA、NVD CVE、CISA KEV、Nuclei、OWASP CRS、MITRE ATT&amp;CK、KISA）</strong>および多様なフォーマット（<code>REST_JSON</code>、<code>STIX_TAXII</code>、<code>YAML_NUCLEI</code>、<code>CRS_CONF</code>、<code>RSS_XML</code>、<code>DOCUMENT_UPLOAD</code>）のセキュリティ情報を単一の標準台帳（<code>watch_security_advisory</code>）へ正規化します。</p><table tabindex="0"><thead><tr><th style="text-align:left;">収集チャネル (<code>source_channel</code>)</th><th style="text-align:left;">8大代表プロバイダー (<code>provider_code</code>)</th><th style="text-align:left;">収集フォーマット</th><th style="text-align:left;">主な正規化抽出項目</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. オープンソースエコシステム勧告</strong></td><td style="text-align:left;"><code>OSV_DEV_FEED</code> (OSV.dev), <code>GITHUB_GHSA</code> (GitHub GHSA)</td><td style="text-align:left;"><code>REST_JSON</code></td><td style="text-align:left;"><code>MAVEN</code>、<code>NPM</code>、<code>PYPI</code>、<code>GO</code>、<code>DOCKER</code>パッケージ別の脆弱バージョン範囲およびパッチ適用済みバージョン</td></tr><tr><td style="text-align:left;"><strong>2. グローバルCVEデータベース</strong></td><td style="text-align:left;"><code>NVD_CVE_FEED</code> (NIST NVD CVE)</td><td style="text-align:left;"><code>REST_JSON</code></td><td style="text-align:left;">CVE ID、CVSS v3.1スコア、CWEコード、影響を受けるCPE/パッケージバージョン範囲</td></tr><tr><td style="text-align:left;"><strong>3. 実戦悪用確認済み脆弱性</strong></td><td style="text-align:left;"><code>CISA_KEV_CATALOG</code> (CISA KEV)</td><td style="text-align:left;"><code>REST_JSON</code></td><td style="text-align:left;">実際のハッキングで悪用中の脆弱性（<code>ACTIVE_EXPLOIT</code>）、必須対応期限、緩和策ガイドライン</td></tr><tr><td style="text-align:left;"><strong>4. ペネトレーションテスト・脆弱性スキャナーテンプレート</strong></td><td style="text-align:left;"><code>NUCLEI_TEMPLATES</code> (Nuclei)</td><td style="text-align:left;"><code>YAML_NUCLEI</code></td><td style="text-align:left;">HTTPリクエストメソッド・パス、攻撃ペイロードプローブ、マッチャー（Matcher）正規表現</td></tr><tr><td style="text-align:left;"><strong>5. WAF &amp; 攻撃戦術マトリックス</strong></td><td style="text-align:left;"><code>OWASP_CRS_FEED</code> (OWASP CRS), <code>MITRE_ATTACK_STIX</code> (MITRE ATT&amp;CK)</td><td style="text-align:left;"><code>CRS_CONF</code> / <code>STIX_TAXII</code></td><td style="text-align:left;">SQLi/XSS/RCE/LFI検知正規表現、ターゲット位置（<code>HEADER</code>、<code>URI</code>、<code>QUERY</code>、<code>BODY</code>）、構文指紋、MITRE戦術コード（<code>T1190</code>など）</td></tr><tr><td style="text-align:left;"><strong>6. 国内セキュリティ勧告および診断ドキュメント</strong></td><td style="text-align:left;"><code>KISA_BOHO_NOTICE</code> (KISA保護ナラ), 社内診断書アップロード</td><td style="text-align:left;"><code>RSS_XML</code> / <code>DOC</code></td><td style="text-align:left;">KISAセキュリティ通知、外部ペネトレーションテスト結果報告書（PDF/Markdown）の解析および正規化</td></tr></tbody></table><hr><h2 id="_2-5段階ssrf防御ガード-5-stage-ssrf-defense-guard" tabindex="-1">2. 5段階SSRF防御ガード（5-Stage SSRF Defense Guard） <a class="header-anchor" href="#_2-5段階ssrf防御ガード-5-stage-ssrf-defense-guard" aria-label="Permalink to “2. 5段階SSRF防御ガード（5-Stage SSRF Defense Guard）”">​</a></h2><p>外部フィードURLを同期したり、Webhookでセキュリティ勧告を収集したりする際に内部ネットワークへの侵入（SSRF）攻撃に悪用されないよう、<code>SyncWatch</code>のすべてのアウトバウンド収集リクエストは<strong>5段階SSRF防御ガード</strong>を通過する必要があります。</p>',9)),(t(),i(E,null,{default:c(()=>[l(a,{id:"mermaid-124",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Req%5B%22%E5%A4%96%E9%83%A8%E3%83%95%E3%82%A3%E3%83%BC%E3%83%89%E5%90%8C%E6%9C%9F%E3%83%AA%E3%82%AF%E3%82%A8%E3%82%B9%E3%83%88%20(feed_url)%22%5D%20--%3E%20S1%5B%22Stage%201%3A%20%E3%83%97%E3%83%AD%E3%83%88%E3%82%B3%E3%83%AB%E3%81%8A%E3%82%88%E3%81%B3%E3%83%9D%E3%83%BC%E3%83%88%E6%A4%9C%E8%A8%BC%20(HTTPS%E5%B0%82%E7%94%A8%E3%80%81%E9%9D%9E%E6%A8%99%E6%BA%96%E3%83%9D%E3%83%BC%E3%83%88%E3%82%92%E9%81%AE%E6%96%AD)%22%5D%0A%20%20%20%20S1%20--%3E%20S2%5B%22Stage%202%3A%20%E3%83%9B%E3%82%B9%E3%83%88%E5%90%8D%E3%83%9B%E3%83%AF%E3%82%A4%E3%83%88%E3%83%AA%E3%82%B9%E3%83%88%20%26%20%E3%83%AA%E3%83%86%E3%83%A9%E3%83%ABIP%E6%A4%9C%E8%A8%BC%22%5D%0A%20%20%20%20S2%20--%3E%20S3%5B%22Stage%203%3A%20DNS%E5%90%8D%E5%89%8D%E8%A7%A3%E6%B1%BA%E3%81%8A%E3%82%88%E3%81%B3%E3%83%97%E3%83%A9%E3%82%A4%E3%83%99%E3%83%BC%E3%83%88%2F%E3%83%AB%E3%83%BC%E3%83%97%E3%83%90%E3%83%83%E3%82%AF%2F%E3%83%A1%E3%82%BF%E3%83%87%E3%83%BC%E3%82%BF%E5%B8%AF%E5%9F%9F%E3%81%AE%E9%81%AE%E6%96%AD%22%5D%0A%20%20%20%20S3%20--%3E%20S4%5B%22Stage%204%3A%20HTTP%E3%83%AA%E3%83%80%E3%82%A4%E3%83%AC%E3%82%AF%E3%83%88%E3%81%AE%E7%84%A1%E5%8A%B9%E5%8C%96%20(%E3%81%BE%E3%81%9F%E3%81%AF%E3%83%9B%E3%83%83%E3%83%97%E3%81%94%E3%81%A8%E3%81%AE%E5%86%8D%E6%A4%9C%E8%A8%BC)%22%5D%0A%20%20%20%20S4%20--%3E%20S5%5B%22Stage%205%3A%20%E3%83%AC%E3%82%B9%E3%83%9D%E3%83%B3%E3%82%B9%E3%82%B9%E3%83%88%E3%83%AA%E3%83%BC%E3%83%A0%E3%82%B5%E3%82%A4%E3%82%BA%E4%B8%8A%E9%99%90%20(Max%20Bytes)%20%26%20%E5%8E%B3%E6%A0%BC%E3%81%AA%E3%82%BF%E3%82%A4%E3%83%A0%E3%82%A2%E3%82%A6%E3%83%88%22%5D%0A%20%20%20%20S5%20--%3E%20Norm%5B%22%E6%AD%A3%E8%A6%8F%E5%8C%96%E3%83%91%E3%83%BC%E3%82%B5%E3%83%BC%20(watch_security_advisory%20%E6%A0%BC%E7%B4%8D)%22%5D%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<ol><li><strong>Stage 1 — スキームおよびポートの強制</strong>: <code>https://</code>スキーム（デフォルト443ポート）のみを許可し、<code>file://</code>、<code>gopher://</code>、<code>ftp://</code>、<code>ldap://</code>などの非標準スキームを即座に遮断します。</li><li><strong>Stage 2 — 登録済みプロバイダードメイン検証</strong>: <code>watch_feed_source</code>に登録・承認されたプロバイダードメインであるかを確認し、URL内のユーザー資格情報（<code>user:pass@host</code>）の挿入を拒否します。</li><li><strong>Stage 3 — DNS Rebindingおよびプライベート帯域の遮断</strong>: ソケット接続の直前にDNSを名前解決し、ループバック（<code>127.0.0.0/8</code>、<code>::1</code>）、プライベートネットワーク（<code>10.0.0.0/8</code>、<code>172.16.0.0/12</code>、<code>192.168.0.0/16</code>）、リンクローカルおよびクラウドメタデータ（<code>169.254.169.254</code>）IPへ解決された場合は即座に接続を拒否します。</li><li><strong>Stage 4 — リダイレクト（3xx）チェーンの統制</strong>: 無秩序なオープンリダイレクトを通じた内部ネットワークへの迂回を防ぐため、自動リダイレクトを無効化するか、すべての遷移先URLに対してStage 1〜3を再実行します。</li><li><strong>Stage 5 — ペイロードボム防御</strong>: レスポンス<code>Content-Type</code>検証とともに最大受信バイト上限（例：10MB）および読み取りタイムアウトを強制し、メモリ枯渇（OOM）を防止します。</li></ol><hr><h2 id="_3-watchrulecompilerserviceデュアルルールコンパイルおよび独自サンドボックス検証" tabindex="-1">3. <code>WatchRuleCompilerService</code>デュアルルールコンパイルおよび独自サンドボックス検証 <a class="header-anchor" href="#_3-watchrulecompilerserviceデュアルルールコンパイルおよび独自サンドボックス検証" aria-label="Permalink to “3. WatchRuleCompilerServiceデュアルルールコンパイルおよび独自サンドボックス検証”">​</a></h2><p>正規化されたセキュリティアドバイザリ（<code>watch_security_advisory</code>）が格納されると、<code>WatchRuleCompilerService</code>はこれを分析して2種類の実行可能なセキュリティルールへと同時にコンパイルします。</p><h3 id="_3-1-デュアルコンパイル成果物" tabindex="-1">3.1 デュアルコンパイル成果物 <a class="header-anchor" href="#_3-1-デュアルコンパイル成果物" aria-label="Permalink to “3.1 デュアルコンパイル成果物”">​</a></h3><ul><li><strong>Shift-Left点検ルール (<code>watch_verse_audit_rule</code> → <code>VerseAuditPack</code>)</strong>: <ul><li><strong>SCA依存関係ルール (<code>SCA_DEPENDENCY</code>)</strong>: エコシステム（<code>MAVEN</code>、<code>NPM</code>など）、パッケージ座標（<code>package_name</code>）、脆弱バージョン範囲（<code>vulnerable_version_range</code>）、安全なパッチバージョン（<code>patched_version</code>）を明記します。</li><li><strong>SAST静的コードルール (<code>SAST_CODE</code>)</strong>: 脆弱なAPI呼び出しや安全でないデシリアライゼーション・クエリ組み立てをソースコードAST/行から検出する正規表現（<code>sast_pattern_regex</code>）と修正ガイド（<code>remediation_guide_md</code>）を含みます。</li><li><strong>DASTペネトレーションテストプローブ (<code>DAST_PENTEST</code>)</strong>: 隔離されたステージング環境で脆弱性の再現可否を点検するHTTPメソッド（<code>dast_probe_method</code>）、パス（<code>dast_probe_path</code>）、ペイロード（<code>dast_probe_payload</code>）を生成します。</li></ul></li><li><strong>Shift-Right防御ルール (<code>watch_apim_defense_rule</code> → <code>ApimDefensePack</code>)</strong>: <ul><li><strong>構文トークン指紋 (<code>grammar_fingerprint</code>)</strong>: <code>SqlXssLexicalTokenizer</code>が抽出するSQLi/XSS構文トークンシーケンス指紋（例：<code>s&amp;1</code>、<code>sUE</code>、<code>;k</code>、<code>x_script</code>）をマッピングします。</li><li><strong>位置別精密正規表現 (<code>detection_regex</code> &amp; <code>target_locations</code>)</strong>: <code>HEADER</code>、<code>URI</code>、<code>QUERY</code>、<code>BODY</code>のうち検査が必要なターゲット位置とエンドポイントパスパターン（<code>target_path</code>）を指定します。</li><li><strong>Restricted SpEL防御表現式 (<code>defense_expression</code>)</strong>: <code>SimpleEvaluationContext</code>ベースの安全なサンドボックス表現式により、複合条件（ヘッダー + クエリ + 構文指紋の組み合わせ）を評価します。</li></ul></li></ul><h3 id="_3-2-独自隔離サンドボックス検証-self-sandbox-verification" tabindex="-1">3.2 独自隔離サンドボックス検証（Self-Sandbox Verification） <a class="header-anchor" href="#_3-2-独自隔離サンドボックス検証-self-sandbox-verification" aria-label="Permalink to “3.2 独自隔離サンドボックス検証（Self-Sandbox Verification）”">​</a></h3><p>コンパイルされたすべての<code>watch_apim_defense_rule</code>は、全社配信前に必ず独自サンドボックス検証器を通過する必要があります。</p><ol><li><strong>Positive Samples検証 (<code>positive_samples_json</code>)</strong>: 実際の攻撃ベクトルサンプルを注入し、100%検知（<code>tp_rate = 100.00</code>）されるかを確認します。</li><li><strong>Negative Samples検証 (<code>negative_samples_json</code>)</strong>: 正常なビジネスAPIリクエストサンプルを注入し、誤検知が0件（<code>fp_rate = 0.00</code>）であるかを確認します。</li><li><strong>ReDoSタイムアウト検証</strong>: 正規表現およびSpEL評価時間が1件あたり<code>0.5ms</code>を超過しないかを測定し、検証を通過したルールのみが<code>sandbox_verified = true</code>、<code>dispatch_status = &#39;READY&#39;</code>状態へ昇格します。</li></ol>',9))])}const f=d(S,[["render",A]]);export{C as __pageData,f as default};
